 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Each occupied source cell is expanded into the complement of the
    # source's binary mask, preserving the cell's color.
    mask = [[value == 0 for value in row] for row in grid]
    out = [[0 for _ in range(w * h)] for _ in range(h * w)]
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color != 0:
                for dr in range(h):
                    for dc in range(w):
                        if mask[dr][dc]:
                            out[r * h + dr][c * w + dc] = color
    return out
